[1450] = { en = "Gryphon Master Talonaxe", tier = 3,
  t = "Gryphon Master Talonaxe",
  d = "Dus jij bent een veredelde $gloopjongen:loopmeid; voor een of andere ouwe vent van de Explorers' League, hè?$b$bNou, luister jij eens naar mij, $c. Ik weet niet met wie jouw oude maatje daar beneden in Azeroth rondvloog. Zie ik eruit als Gryphon Master Talonaxe? Nou?$b$bAls je zo geïnteresseerd bent in de vluchtopdrachten, waarom vraag je het dan niet aan de griffioenmeester? Als ik je hier nog veel langer zie rondhangen, zet ik je aan het echte werk.$b$bEn nu opschieten.",
  o = "Praat met Gryphon Master Talonaxe in de Aerie Peak Aviary.",
  c = "Ah, ja. Natuurlijk weet ik nog dat ik een van mijn griffioenrijders stuurde om Brohann Caskbelly een handje te helpen.$b$bIk heb altijd een zwak gehad voor de Explorers' League. Mijn vader hielp trouwens bij het eerste opgravingsteam dat Uldaman ontdekte.$b$bIk stuurde met Brohann de rijder mee die ik toen voor mijn beste griffioenrijder hield. Het was een kerel die Rhapsody Shindigger heette.$b$bEn wat was dat een griffioenjockey! Nou ja, tot...",
  g = { {"veredelde", "glorified (veredeld)"}, {"loopjongen", "errand boy"}, {"loopmeid", "errand girl"}, {"ouwe vent", "old geezer"}, {"maatje", "buddy"}, {"vluchtopdrachten", "flight assignments (vluchtopdracht)"}, {"griffioenmeester", "gryphon master"}, {"rondhangen", "to hang around, idle"}, {"opschieten", "to hurry up, get a move on"}, {"een handje te helpen", "to lend a hand (een handje helpen)"}, {"een zwak", "a soft spot (een zwak hebben voor)"}, {"opgravingsteam", "excavation team"}, {"kerel", "chap, fellow"}, {"griffioenjockey", "gryphon jockey"} },
},

[1451] = { en = "Rhapsody Shindigger", tier = 3,
  t = "Rhapsody Shindigger",
  d = "Rhapsody hield nogal van de drank. Begrijp me niet verkeerd -- alle dwergen hier bij de volière houden van een goed biertje op het juiste moment.$b$bMaar die ouwe Shindigger voelde zich bij de drank zo thuis als een griffioen in de lucht. En dat was ook verdomd jammer. Niemand kon vliegen zoals Rhapsody.$b$bHet eerste teken van problemen was toen hij strompelend terugkwam van die missie met jouw maatje Brohann. Daarna ging het snel bergafwaarts. We moesten hem ontslaan.$b$bHet laatste wat ik hoorde, is dat hij ten oosten van hier een brouwkamp heeft opgezet...",
  o = "Zoek Rhapsody Shindigger op in The Hinterlands.",
  c = "Hik!$b$bIk kijk je recht aan, maar je blijft maar op en neer dobberen. Ik word er duizelig van. Hoho!$b$bHik!$b$bWow! Voelde je dat? De grond schudt, vriend. Ik heb een drankje nodig.$b$bHik!",
  g = { {"begrijp me niet verkeerd", "don't get me wrong"}, {"volière", "aviary"}, {"voelde zich ... thuis", "took to, felt at home (zich thuis voelen)"}, {"verdomd jammer", "a damned shame"}, {"strompelend", "stumbling (strompelen)"}, {"bergafwaarts", "downhill"}, {"ontslaan", "to let go, dismiss"}, {"brouwkamp", "brew camp"}, {"hik", "hiccup"}, {"dobberen", "to bob"}, {"duizelig", "dizzy"}, {"schudt", "shakes (schudden)"} },
},

[1452] = { en = "Rhapsody's Kalimdor Kocktail", tier = 3,
  t = "De Kalimdor Kocktail van Rhapsody",
  d = "Hik!$b$bDus die gekke Brohann heeft je gestuurd? Tjonge, wat hebben wij een avontuur beleefd... Hik!$b$bAls je wilt dat ik vertel wat er in het moeras gebeurde, heb ik eerst iets sterks te drinken nodig. Het was geen mooi gezicht, snap je. Hik!$b$bWeet je wat... breng me wat ik nodig heb om een Kalimdor Kocktail in elkaar te flansen, dan vertel ik je er alles over.$b$bIk heb wat Roc-spiermagen uit Tanaris nodig... en eens kijken... wat Groddoc- en Ironfur-levers uit Feralas...$b$bEen lekker sterke Kalimdor Kocktail... daar ga ik wel van praten!",
  o = "Rhapsody Shindigger in The Hinterlands wil dat je hem 3 Roc Gizzards, 3 Groddoc Livers en 3 Ironfur Livers brengt.",
  p = "Heb je ooit een Rhapsody Malt gehad? Een van mijn beste brouwsels, al zeg ik het zelf. Hik!$b$bMaar als ik de verschrikkingen van die noodlottige vlucht boven... hik... het moeras opnieuw moet beleven, dan heb ik iets nodig dat een tikje sterker is. Hik!$b$bJe hebt zeker nog niet die spiermagen en levers gevonden die ik nodig heb om mijn Kalimdor Kocktail dat beetje extra kick te geven?$b$bHik!",
  c = "Ik zie dat je helemaal geen moeite had om me te brengen wat ik nodig heb! Dat moet een flinke klus geweest zijn, daar in het verre Kalimdor.$b$bHet duurt maar even voordat ik uit deze spiermagen en levers heb gehaald wat ik nodig heb. Hik!$b$bDan kan ik een woest sterk drankje stoken en je eindelijk vertellen wat je wilt weten.$b$bHik!$b$bIk krijg al rillingen als ik alleen maar aan dat ouwe moeras denk.$b$bHik!$b$bIk flans snel even een drankje in elkaar.",
  g = { {"tjonge", "my, boy (exclamation)"}, {"beleefd", "experienced (beleven)"}, {"moeras", "swamp"}, {"geen mooi gezicht", "not a pretty scene"}, {"in elkaar te flansen", "to whip up (in elkaar flansen)"}, {"spiermagen", "gizzards (spiermaag)"}, {"levers", "livers (lever)"}, {"brouwsels", "brews (brouwsel)"}, {"verschrikkingen", "horrors (verschrikking)"}, {"noodlottige", "fateful (noodlottig)"}, {"een tikje", "a wee bit"}, {"stoken", "to distil"}, {"rillingen", "shivers (rilling)"}, {"flans ... in elkaar", "whip up (in elkaar flansen)"} },
},

[1469] = { en = "Rhapsody's Tale", tier = 3,
  t = "Het verhaal van Rhapsody",
  d = "Voor de vlucht dronk ik een heel vat stout leeg. Hik!$b$bEn wat een vlucht was dat. Ik zoefde rond en Brohann volgde me. Maar ik zag geen tempel. Hik!$b$bNou ja, ik zag geen tempel tot ik een beetje te aangeschoten raakte en van mijn rijdier viel. Ik plonsde zo het water in en werd naar beneden gezogen. Opeens was ik omringd door een stel griezelige trollen. Ik ben daar snel weggezwommen, hoor! Ik heb zelfs dit trollensouvenir meegenomen. Hier, breng het naar Brohann en zeg hem dat zijn tempel echt daar beneden ligt. Hik!",
  o = "Breng het Atal'ai Tablet Fragment naar Brohann Caskbelly in Stormwind.",
  p = "Eindelijk ben je terug, $n. Het is al een hele tijd geleden dat we elkaar spraken. Ik dacht al dat je mijn opdracht misschien vergeten was.$b$bHeb je die sluwe griffioenrijder gevonden? Had hij iets te melden?",
  c = "Rhapsody Shindigger! Dat klopt... hoe kon ik zo'n naam vergeten?$b$bDus hij wist al die tijd van het zinken van de tempel? Nou, dat had je zeker wat loopwerk kunnen besparen.$b$bMaar dit artefact van de Atal'ai! Nou, dat is een flinke vondst!",
  g = { {"vat", "keg, barrel"}, {"zoefde", "zipped, whizzed (zoeven)"}, {"aangeschoten", "tipsy"}, {"rijdier", "mount"}, {"plonsde", "plunged, splashed (plonzen)"}, {"gezogen", "sucked (zuigen)"}, {"omringd", "surrounded (omringen)"}, {"griezelige", "creepy (griezelig)"}, {"sluwe", "wily, sly (sluw)"}, {"te melden", "to report (melden)"}, {"zinken", "sinking"}, {"loopwerk", "leg work"}, {"besparen", "to save, spare"}, {"vondst", "find, discovery"} },
},

[1690] = { en = "Wastewander Justice", tier = 3,
  t = "Gerechtigheid voor de Wastewander",
  d = "Hé, jij daar! Het is tijd dat je de Gadgetzan Water Company eens flink helpt.$B$BDe Wastewander-nomaden in de woestijn van Tanaris hebben bijna alle waterputten in beslag genomen! Als we er niet bij kunnen, is onze watervoorraad in een mum van tijd opgedroogd. Als je bij ons in een goed blaadje wilt komen, help je ons om gerechtigheid te brengen bij die nomaden!$B$BGa hiervandaan naar het oosten en versla tien Wastewander Bandits en Thieves. Meld je daarna meteen weer bij mij. Gerechtigheid wacht op geen enkele man... goblin... bah, ga nou maar gewoon!",
  o = "Versla 10 Wastewander Bandits en Thieves ten oosten van Gadgetzan. Meld je daarna bij Chief Engineer Bilgewhizzle.",
  p = "Nu al terug? Ik hoop dat je die Wastewander Bandits en Thieves gerechtigheid op goblinmanier hebt gebracht, zoals ik je had gevraagd!",
  c = "Dat noem ik nou efficiënt! Je hebt het aantal nomaden zo ver teruggebracht dat we kunnen gaan nadenken over hoe we die waterputten terugwinnen.$B$BDe Gadgetzan Water Company bedankt je voor je hulp, maar we zijn nog lang niet klaar met die smerige nomaden. Luister goed - dit hebben we nu nodig...",
  g = { {"gerechtigheid", "justice"}, {"nomaden", "nomads (nomade)"}, {"waterputten", "water wells (waterput)"}, {"in beslag genomen", "seized (in beslag nemen)"}, {"watervoorraad", "water supply"}, {"in een mum van tijd", "in no time"}, {"opgedroogd", "dried up (opdrogen)"}, {"in een goed blaadje", "in someone's good graces"}, {"efficiënt", "efficient"}, {"teruggebracht", "brought down, reduced (terugbrengen)"}, {"terugwinnen", "to win back"}, {"smerige", "foul, filthy (smerig)"} },
},

[1691] = { en = "More Wastewander Justice", tier = 3,
  t = "Meer gerechtigheid voor de Wastewander",
  d = "Nu moet je de sterkere groepen van de Wastewander-nomaden aanpakken. Je hebt tot nu toe goed werk gedaan. Maar als we die waterputten willen terugnemen, is het logisch om dat tegen zo weinig mogelijk nomaden te doen!$B$BDeze keer moet je hun schurken, sluipmoordenaars en schaduwmagiërs verslaan. Je vindt ze ten oosten en ten zuidoosten van hier.$B$BIk ga niet tegen je liegen - het is een gemeen stelletje. Maar als je dit voor ons doet, zijn we op weg om terug te nemen wat echt van ons is!",
  o = "Versla 10 Wastewander Shadow Mages, 8 Wastewander Rogues en 6 Wastewander Assassins voor Chief Engineer Bilgewhizzle in Gadgetzan.",
  p = "En, heb je die nomaden kunnen uitschakelen zoals ik vroeg? De Gadgetzan Water Company maakt plannen op basis van jouw succes hier! Laat ons nu niet in de steek...",
  c = "Werk van topkwaliteit, $n... echt top! Je hebt het aantal nomaden zo ver teruggebracht dat we nu echt de strijd naar hen toe kunnen brengen!$B$BAls je het nog niet gedaan hebt, praat dan met Spigot Operator Luglunket hier. Hij geeft een beloning voor alle Wastewander-waterzakken die je misschien bent tegengekomen terwijl je die nomaden hun straf gaf!",
  g = { {"aanpakken", "to take on, deal with"}, {"terugnemen", "to take back"}, {"logisch", "logical, makes sense"}, {"schurken", "rogues, villains (schurk)"}, {"sluipmoordenaars", "assassins (sluipmoordenaar)"}, {"schaduwmagiërs", "shadow mages (schaduwmagiër)"}, {"liegen", "to lie"}, {"stelletje", "bunch, lot"}, {"uitschakelen", "to take out"}, {"op basis van", "based on"}, {"in de steek", "let down (in de steek laten)"}, {"waterzakken", "water pouches (waterzak)"} },
},

[1707] = { en = "Water Pouch Bounty", tier = 3,
  t = "Beloning voor waterzakken",
  d = "Gegroet, $n - ik heet Luglunket, en we hebben een belangrijke klus voor je, als je dat ziet zitten! Hoera!$B$BAls ervaren kraanbediener zou niets me blijer maken dan alle Wastewander-waterzakken aan te nemen die je in de woestijn vindt. Het is toch al ons water - de nomaden hebben het gewoon gestolen, dat is alles! De Gadgetzan Water Company geeft je een officieel hulppakket voor elke vijf die je inlevert. Maar het belangrijkste is: je helpt Gadgetzan om zichzelf te helpen!",
  o = "Breng 5 Wastewander Water Pouches naar Spigot Operator Luglunket in Gadgetzan.",
  p = "Heb je de vijf Wastewander-waterzakken die we nodig hebben? Zo ja, dan krijg je het Gadgetzan Water Company Care Package, Model 103-XB!",
  c = "Uitstekend - hoe meer waterzakken we terugkrijgen, hoe verder we allemaal van een ramp af zijn! Blijf ze brengen, dan zorg ik dat je een beloning krijgt voor elke vijf waterzakken die je me brengt.",
  g = { {"gegroet", "greetings"}, {"klus", "job, task"}, {"als je dat ziet zitten", "if you're up for it (zien zitten)"}, {"ervaren", "experienced, seasoned"}, {"kraanbediener", "spigot operator"}, {"officieel", "official"}, {"hulppakket", "care package"}, {"inlevert", "turn in (inleveren)"}, {"terugkrijgen", "to get back, reclaim"}, {"ramp", "disaster"} },
},

[1878] = { en = "Water Pouch Bounty", tier = 3,
  t = "Beloning voor waterzakken",
  p = "Ben je er weer, $n? Als je nog vijf Wastewander-waterzakken hebt, dan heb ik een hulppakket met jouw naam erop!",
  c = "Uitstekend - hoe meer waterzakken we terugkrijgen, hoe verder we allemaal van een ramp af zijn! Blijf ze brengen, dan zorg ik dat je een beloning krijgt voor elke vijf waterzakken die je me brengt.",
