[3520] = { en = "Screecher Spirits", tier = 3,
  t = "Screecher-geesten",
  d = "Ik zoek de geesten van de vale screechers van Feralas. Ze zijn neven van een oude, oude god, en hun geesten zijn met hem verbonden.$B$BNeem deze braamstaf mee en ga naar Feralas. Zoek vale screechers in het zuiden en het midden van Feralas en versla ze. Zwaai daarna met mijn braamstaf over hun gevallen lichamen. Zo lok je hun geest naar buiten. Raak de geest aan en verzamel zijn essentie.$B$BKom terug met mijn braamstaf en met de verzamelde essentie. Dan vertel ik je meer over de oude god waarover ik sprak.",
  o = "Vang de geesten van 3 screechers in Feralas. Ga daarna terug naar Yeh'kinya in Steamwheedle Port.",
  p = "Heb je de essentie van de screecher-geesten verzameld, $N?",
  c = "Je hebt het goed gedaan, $N. Misschien is het nu tijd om meer te onthullen...$B$BEr bestaat een oude voorspelling onder de trollen: de dode god Hakkar, de Soulflayer, zal op een dag terugkeren naar deze wereld. Sommigen zeggen dat de komst van Hakkar vreugde en glorie zal brengen voor alle trollen. Anderen geloven dat zijn wederopstanding het einde van alles betekent.$B$BIk geloof deze mythe niet, maar ik weet wel dat de essentie van Hakkar grote kracht bezit. Die kracht moet worden weggehouden bij wie er misbruik van zou maken...",
  o1 = "Screecher-geesten verzameld",
  g = { {"neven", "cousins (neef)"}, {"verbonden", "linked, connected (verbinden)"}, {"braamstaf", "bramble wand"}, {"zwaai", "wave (zwaaien)"}, {"lok", "coax, lure (lokken)"}, {"essentie", "essence"}, {"onthullen", "to reveal"}, {"voorspelling", "prophecy, prediction"}, {"vreugde", "joy"}, {"wederopstanding", "resurrection"}, {"mythe", "myth"}, {"bezit", "holds, possesses (bezitten)"}, {"weggehouden", "kept away (weghouden)"}, {"misbruik", "abuse, misuse"} },
},

[2872] = { en = "Stoley's Debt", tier = 3,
  t = "De schuld van Stoley",
  d = "Mijn oude maat Stoley is me een heel speciale fles rum schuldig. Hij staat achter de bar in Steamwheedle Port in Tanaris, Kalimdor. Hij heeft me beloofd dat de rum daar sterker is dan alles wat we in Booty Bay kunnen vinden. Hij is er zo zeker van dat hij zegt: als ik die rum probeer en het niet met hem eens ben, dan betaalt hij me het dubbele van wat hij me schuldig is!$B$BNou, ik denk dat hij niet meer zo zeker is als de laatste keer dat we elkaar spraken. Nu durft hij me die rum niet te geven. Maar ik krabbel nooit terug bij een weddenschap, dus waarom ga jij niet namens mij met hem praten...",
  o = "Praat met Stoley in Steamwheedle Port.",
  c = "Ah, dus je hebt met MacKinley gepraat?$B$BHet is niet wat hij denkt! Ik ben niet bang om hem wat Steamwheedle Bilge Rum te geven...$B$BIk heb gewoon geen rum om hem te geven!",
  g = { {"schuld", "debt"}, {"maat", "buddy, mate"}, {"schuldig", "owes (schuldig zijn)"}, {"beloofd", "promised (beloven)"}, {"het dubbele", "double (the amount)"}, {"durft", "dares (durven)"}, {"krabbel nooit terug", "never back down (terugkrabbelen)"}, {"weddenschap", "bet, wager"}, {"namens", "on behalf of"} },
},

[2873] = { en = "Stoley's Shipment", tier = 3,
  t = "De lading van Stoley",
  d = "Ik ben \"Sea Wolf\" MacKinley in Booty Bay rum schuldig om een weddenschap af te handelen, maar mijn rum is op! Captain Cuergo heeft mijn laatste lading gestolen. Hij heeft die verstopt in dat ommuurde piratenstadje in het zuiden.$B$BAls je mijn lading rum kunt vinden en bij mij terugbrengen, dan kan ik MacKinley bewijzen dat de drank van Kalimdor die van Booty Bay ver achter zich laat!",
  o = "Breng Stoley's Shipment naar Stoley in Steamwheedle Port.",
  p = "Heb je mijn lading rum gevonden, $N?",
  c = "Geweldig, bedankt voor de lading! Nu kunnen MacKinley en ik eindelijk onze weddenschap afhandelen.",
  g = { {"lading", "shipment, cargo"}, {"afhandelen", "to settle"}, {"weddenschap", "bet, wager"}, {"verstopt", "hidden, stowed (verstoppen)"}, {"ommuurde", "walled (ommuurd)"}, {"piratenstadje", "pirate town"}, {"bewijzen", "to prove"}, {"drank", "booze, drink"}, {"ver achter zich laat", "beats by far (ver achter zich laten)"} },
},

[2874] = { en = "Deliver to MacKinley", tier = 3,
  t = "Bezorgen bij MacKinley",
  d = "Nogmaals bedankt voor je hulp, $N. Hier is een fles Steamwheedle bilge rum. Breng die naar MacKinley. Dan kan hij eindelijk ophouden met zijn gekke ideeën over de drank van Booty Bay.",
  o = "Breng Stoley's Bottle naar \"Sea Wolf\" MacKinley in Booty Bay.",
  p = "Is Stoley over de brug gekomen met mijn drank?",
  c = "Hm, eens proberen...$B$BNiet te geloven! Dit spul is... vreselijk! Dat is geweldig!$B$BNou, dan mag Stoley het geld houden dat hij me schuldig is. Hij houdt woord over Steamwheedle bilge rum. Dat spul is zo dik als grind en het brandt als lava!",
  g = { {"bezorgen", "to deliver"}, {"nogmaals", "once again"}, {"ophouden", "to stop"}, {"over de brug gekomen", "coughed up, handed over (over de brug komen)"}, {"niet te geloven", "unbelievable"}, {"spul", "stuff"}, {"vreselijk", "terrible"}, {"houdt woord", "keeps his word (woord houden)"}, {"grind", "gravel"} },
},

[2875] = { en = "WANTED: Andre Firebeard", tier = 3,
  t = "GEZOCHT: Andre Firebeard",
  d = "De gemene piraat Andre Firebeard wordt gezocht voor misdaden tegen Steamwheedle en Gadgetzan.$B$BVolgens besluit van de bestuursraad mag iedereen die dit leest dodelijk geweld gebruiken bij de arrestatie van Andre en zijn handlangers.$B$BVolgens een verder besluit geldt het volgende: als Andre tijdens zijn rechtszaak overleden is of op een andere manier verhinderd is, mag zijn hoofd hem vervangen. Wie dat hoofd aflevert bij Security Chief Bilgewhizzle, sluit daarmee een bindend en uitbetaalbaar contract.",
  o = "Breng Andre's Head naar Security Chief Bilgewhizzle in Steamwheedle Port.",
  p = "Je kijkt een beetje versuft. Heb je onze juridische documenten gelezen?",
  c = "Ah, het hoofd van Andre. Dus hij komt toch nog naar zijn rechtszaak!$B$BHeel erg bedankt, $N. Als je hier even tekent, kan ik je betalen voor je diensten.$B$BMaak je geen zorgen over de kleine lettertjes. Die zijn onschuldig, en... ik denk dat er geen vergrootglas bestaat dat klein genoeg is om ze te lezen.",
  g = { {"gezocht", "wanted (zoeken)"}, {"misdaden", "crimes (misdaad)"}, {"besluit", "decree, decision"}, {"bestuursraad", "governing council"}, {"dodelijk geweld", "lethal force"}, {"arrestatie", "arrest, apprehension"}, {"handlangers", "accomplices, abettors (handlanger)"}, {"rechtszaak", "trial, hearing"}, {"overleden", "deceased (overlijden)"}, {"verhinderd", "unable to attend, indisposed (verhinderen)"}, {"bindend", "binding"}, {"uitbetaalbaar", "payable"}, {"versuft", "dazed"}, {"juridische", "legal (juridisch)"}, {"kleine lettertjes", "small print"}, {"vergrootglas", "magnifying glass"} },
},

[2876] = { en = "Ship Schedules", tier = 3,
  t = "Vaarschema's",
  d = "Deze rol bevat de schema's van ladingen tussen Steamwheedle Port en Booty Bay. Er staan zowel vroegere als toekomstige ladingen in, met de namen van de schepen. Naast de reizen van sommige schepen staan grote X'en, en naast andere staan notities als \"GROTE BUIT\" en \"ZWAAR GEVECHT\".$B$BIemand in Steamwheedle Port zou dit document graag willen zien.",
  o = "Meld de Ship Schedules bij iemand met gezag in Steamwheedle Port.",
  p = "Je bent buiten adem. Heb je me iets te vertellen?",
  c = "O jee, dit lijkt wel een lijst met vertrek- en aankomsttijden van schepen, met precieze data en tijden en alles!  Als de kapitein van een piratenschip dit in handen kreeg, zou hij de dag van zijn leven hebben!$B$BZeg je dat je dit van een piraat hebt? Nou, dat is verontrustend nieuws...$B$BDank je, $N. Ik ben blij dat je het van hem hebt afgepakt, en ik ben blij dat die piraat nu in het zand bijt!",
  g = { {"vaarschema's", "ship schedules (vaarschema)"}, {"rol", "scroll"}, {"bevat", "contains (bevatten)"}, {"zowel", "both (zowel ... als)"}, {"notities", "notes, annotations (notitie)"}, {"buit", "loot"}, {"gezag", "authority"}, {"buiten adem", "out of breath"}, {"vertrek- en aankomsttijden", "departure and arrival times"}, {"de dag van zijn leven", "a field day, the time of his life"}, {"verontrustend", "disturbing"}, {"afgepakt", "taken away (afpakken)"}, {"in het zand bijt", "is eating dirt, bites the dust (in het zand bijten)"} },
},

[2880] = { en = "Troll Necklace Bounty", tier = 3,
  t = "Beloning voor trollenkettingen",
  d = "Begrijp dit goed, $r - wij horen NIET bij de Alliance! De Wildhammers zijn onafhankelijk. Bij ons bewijs je je waarde met daden, niet met het geklets van mensen die met kletspraat hun luie houding opblazen!$B$BAls je hier vrienden zoekt, bewijs dan eerst wat je waard bent! De smerige trollen die de heuvels van de Hinterlands overspoelen, hebben soms stammenkettingen bij zich. Breng er vijf naar mij, dan schrijven we dat op als een stap in de goede richting voor jou.",
  o = "Breng 5 Troll Tribal Necklaces naar Fraggar Thundermantle in Aerie Peak.",
  p = "Ik wil vijf van die stammenkettingen die de trollen bij zich dragen. Moet ik het nog duidelijker uitleggen? Als je er een doodt, heb je een goede kans dat je er een krijgt!$B$BBewijs je waarde aan de Wildhammers!",
  c = "Zo mag ik het horen! Zie je - deze kettingen bewijzen dat je bereid bent om je handen vuil te maken. Wij Wildhammers vinden dat belangrijk bij wie we mee omgaan.$B$BAls je zo doorgaat, kom je toch nog bij ons in een goed blaadje.",
